/**
 * `agent/channels/*.ts`: HTTP surfaces beyond the session API.
 */
import { join } from "node:path";
import { getDefinitionKind } from "../brand.js";
import { displayPath, pushConfigDiagnostic, pushModuleLoadDiagnostic, } from "./context.js";
import { isDirectory, isModuleFile, moduleStem, sortedEntries } from "./fs.js";
import { validateName } from "./names.js";
export async function loadChannels(ctx, channelsDir, mode = "agent", onDisable) {
    const channels = [];
    let httpChannelDefinition;
    if (!(await isDirectory(channelsDir))) {
        return { channels, httpChannelDefinition };
    }
    for (const entry of await sortedEntries(channelsDir)) {
        const entryPath = join(channelsDir, entry.name);
        if (!entry.isFile() || !isModuleFile(entry.name)) {
            continue;
        }
        const id = moduleStem(entry.name);
        if (!validateName(ctx, "channel", id, entryPath)) {
            continue;
        }
        let mod;
        try {
            mod = await ctx.importModule(entryPath);
        }
        catch (error) {
            pushModuleLoadDiagnostic(ctx, entryPath, error);
            continue;
        }
        const kind = getDefinitionKind(mod.default);
        if (kind === "disabled") {
            onDisable?.(id, entryPath);
            continue;
        }
        if (kind === "http-channel") {
            if (mode === "extension" || id !== "http") {
                pushConfigDiagnostic(ctx, {
                    severity: "error",
                    path: displayPath(ctx, entryPath),
                    message: mode === "extension"
                        ? "The built-in HTTP session channel belongs to the agent; an extension cannot contribute it."
                        : "The built-in HTTP session channel is reserved for the `http` channel id.",
                });
                continue;
            }
            // oxlint-disable-next-line typescript/no-unsafe-type-assertion -- the loader already checked this definition brand; importDefault returns unknown
            httpChannelDefinition = mod.default;
            continue;
        }
        if (kind !== "channel") {
            if (id === "http" && mode === "agent") {
                pushConfigDiagnostic(ctx, {
                    severity: "error",
                    path: displayPath(ctx, entryPath),
                    message: "The channel id `http` is reserved for the built-in HTTP session channel.",
                });
            }
            else {
                ctx.diagnostics.push({
                    severity: "error",
                    code: "invalid_definition",
                    path: displayPath(ctx, entryPath),
                    message: "Channel modules must default-export defineChannel({ ... }).",
                });
            }
            continue;
        }
        if (id === "http" && mode === "agent") {
            pushConfigDiagnostic(ctx, {
                severity: "error",
                path: displayPath(ctx, entryPath),
                message: "The channel id `http` is reserved for the built-in HTTP session channel.",
            });
            continue;
        }
        // oxlint-disable-next-line typescript/no-unsafe-type-assertion -- the loader already checked this definition brand; importDefault returns unknown
        const definition = mod.default;
        for (const notice of definition.meta?.deprecations ?? []) {
            pushConfigDiagnostic(ctx, {
                severity: "warning",
                path: displayPath(ctx, entryPath),
                message: notice,
            });
        }
        channels.push({ id, definition });
    }
    return { channels, httpChannelDefinition };
}
